import sys
from fractions import Fraction


def main():
    data = sys.stdin.read().split()
    n, m = int(data[0]), int(data[1])
    g = [[] for _ in range(n)]
    for i in range(m):
        u = int(data[2 + 3 * i])
        v = int(data[3 + 3 * i])
        g[u].append((v, Fraction(data[4 + 3 * i])))
    found = [False]

    def dfs(start, u, prod, seen):
        for v, r in g[u]:
            p = prod * r
            if v == start:
                if p > 1:
                    found[0] = True
            elif v > start and v not in seen:
                seen.add(v)
                dfs(start, v, p, seen)
                seen.discard(v)

    for s in range(n):
        dfs(s, s, Fraction(1), {s})
    print('YES' if found[0] else 'NO')


main()

